def parse(line):
    fields = []
    field = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
        elif line[i] == ',':
            fields.append(''.join(field))
            field = []
            i += 1
        else:
            field.append(line[i])
            i += 1

    fields.append(''.join(field))
    return fields
```

