```python
def coins(amount, denoms):
    if amount < 0:
        return -1
    if amount == 0:
        return 0

    denoms = [d for d in denoms if d > 0]
    if not denoms:
        return -1

    inf = float("inf")
    dp = [inf] * (amount + 1)
    dp[0] = 0

    for d in denoms:
        for a in range(d, amount + 1):
            if dp[a - d] + 1 < dp[a]:
                dp[a] = dp[a - d] + 1

    return dp[amount] if dp[amount] != inf else -1
```

