from collections import deque
def steps(begin, end, wordlist):
    words=set(wordlist)
    if end not in words:return -1
    q=deque([(begin,1)])
    seen={begin}
    while q:
        word,d=q.popleft()
        if word==end:return d
        for nxt in words:
            if nxt not in seen and len(nxt)==len(word) and sum(a!=b for a,b in zip(word,nxt))==1:
